// @ts-check
/**
 * Native settings for the main app target that no library plugin covers. Extension targets
 * get their own entitlements from targets/<name>/expo-target.config.js.
 * Everything here is regenerated by `npx expo prebuild --clean` — never edit ios/ or android/.
 */
const {
  withEntitlementsPlist,
  withInfoPlist,
  withAndroidManifest,
  withAppBuildGradle,
  createRunOncePlugin,
} = require('expo/config-plugins');

/** @type {import('expo/config-plugins').ConfigPlugin} */
const withIos = (config) => {
  config = withEntitlementsPlist(config, (c) => {
    // Screen Time API. Requires Apple's approval for distribution — see README.
    c.modResults['com.apple.developer.family-controls'] = true;
    return c;
  });
  config = withInfoPlist(config, (c) => {
    // Focus countdown on the Lock Screen / Dynamic Island.
    c.modResults.NSSupportsLiveActivities = true;
    return c;
  });
  return config;
};

/** @type {import('expo/config-plugins').ConfigPlugin} */
const withAndroid = (config) =>
  withAndroidManifest(config, (c) => {
    // Permissions, the watcher service, block activity and Glance receiver are declared in
    // modules/blocker-android's manifest (merged at build time). This just makes sure the
    // template's default backup rules don't sync blocking state to a new device mid-rule.
    const app = c.modResults.manifest.application?.[0];
    if (app) app.$['android:allowBackup'] = 'false';
    return c;
  });

const CXX_MARKER = '// untangle: short native build dir';

/**
 * Windows only: React Native's codegen object paths (absolute source path mangled into the
 * object name) exceed 260 chars. The SDK's default ninja (CMake 3.22, ninja 1.10) can't open
 * them, so the app's native build uses CMake 3.31 (ninja 1.12, long-path aware: requires
 * Windows LongPathsEnabled=1, see README) in a short folder.
 * Overrides: UNTANGLE_CMAKE_VERSION, UNTANGLE_CXX_DIR.
 * @type {import('expo/config-plugins').ConfigPlugin}
 */
const withShortCxxDir = (config) =>
  withAppBuildGradle(config, (c) => {
    if (c.modResults.contents.includes(CXX_MARKER)) return c;
    c.modResults.contents = c.modResults.contents.replace(
      /\nandroid \{\n/,
      `\nandroid {\n    ${CXX_MARKER}\n` +
        `    if (System.getProperty("os.name").toLowerCase().contains("windows")) {\n` +
        `        externalNativeBuild {\n` +
        `            cmake {\n` +
        `                version = System.getenv("UNTANGLE_CMAKE_VERSION") ?: "3.31.6"\n` +
        `                buildStagingDirectory = new File(System.getenv("UNTANGLE_CXX_DIR") ?: "C:/ucx")\n` +
        `            }\n` +
        `        }\n` +
        `    }\n`,
    );
    return c;
  });

/** @type {import('expo/config-plugins').ConfigPlugin} */
const withUntangleNative = (config) => withShortCxxDir(withAndroid(withIos(config)));

module.exports = createRunOncePlugin(withUntangleNative, 'with-untangle-native', '0.1.0');
